test("repro", async () => {
  let n = 0;
  const inner = z.string().default(() => {
    n++;
    return "d";
  });
  const schema = z.object({ TEST: inner });
  schema.parse({});
  const sync = n;
  n = 0;
  await schema.parseAsync({});
  const asyncN = n;
  n = 0;
  inner.parse(undefined);
  const bare = n;
  n = 0;
